function consecutiveNumbersSum(n) {
  // Slide a window [low, high] over 1..n and count the windows whose sum is n.
  let ways = 0, low = 1, total = 0;
  for (let high = 1; high <= n; high++) {
    total += high;
    while (total > n) { total -= low; low++; }
    if (total === n) ways++;
  }
  return ways;
}

